head.script:
scwin.unitTest = function() {
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('tabControl1').setSelectedTabIndex(1)");
    WebSquare.wUnit.addCommand("pause", "50");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('tabControl1').getSelectedTabIndex() == 1", "true");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('tabControl1').setSelectedTabIndex('2')");
    WebSquare.wUnit.addCommand("pause", "50");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('tabControl1').getSelectedTabIndex() == 2", "true");
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
}
